mapper.select:

SELECT COALESCE(SUM(CASE WHEN d.production_confirmation_status=#{inputSUCCEEDED}
     AND d.production_confirmed_at IS NOT NULL AND d.production_stock_applied=TRUE
     AND COALESCE(d.production_void_result_status,'')!=#{inputSUCCEEDED}
     THEN d.production_output_qty ELSE 0 END),0) AS confirmedQty,
COALESCE(SUM(CASE WHEN d.production_confirmation_status IN (#{inputSUBMITTING},#{inputUNKNOWN})
     OR d.production_void_result_status IN (#{inputSUBMITTING},#{inputUNKNOWN})
     THEN d.production_output_qty ELSE 0 END),0)
AS reservedQty

AND d.source_execution_id=#{executionId}
